		if os.IsNotExist(err) {
			return "", nil
		}
		return "", err
	}
	componentDir := filepath.Join(backupRoot, component)
	version, err := nextVersion(componentDir)
	if err != nil {
		return "", err
	}
	dst := filepath.Join(componentDir, fmt.Sprintf("v%d", version))
	if err := os.MkdirAll(dst, 0o755); err != nil {
		return "", err
